65: // because the OpenCode transcript is a single JSON object.
66: func compactOpenCode(content []byte, opts MetadataFields) ([]byte, error) {
67: 	var session struct {
68: 		Messages []openCodeMessage `json:"messages"`
69: 	}
70: 	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
