216: func (a *OpenCodeAgent) WriteSession(ctx context.Context, session *agent.AgentSession) error {
217: 	if session == nil {
218: 		return errors.New("nil session")
219: 	}
220: 	if len(session.NativeData) == 0 {
221: 		return errors.New("no session data to write")
222: 	}
223: 
224: 	// Import the session into OpenCode's database.
225: 	// This enables `opencode -s <id>` to resume the restored session.
226: 	return a.importSessionIntoOpenCode(ctx, session.SessionID, session.NativeData)
227: }
