276: // isOutdated compares current and latest versions using semantic versioning.
277: // Returns true if current < latest.
278: func isOutdated(current, latest string) bool {
279: 	// Ensure versions have "v" prefix for semver package
280: 	if !strings.HasPrefix(current, "v") {
281: 		current = "v" + current
282: 	}
283: 	if !strings.HasPrefix(latest, "v") {
284: 		latest = "v" + latest
285: 	}
286: 
287: 	// Local/unreleased builds shouldn't trigger update notifications.
288: 	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
289: 	if isDevBuild(current) {
290: 		return false
291: 	}
292: 
293: 	// semver.Compare returns -1 if current < latest
294: 	return semver.Compare(current, latest) < 0
295: }
